/**
 * Info card renderer for the Austrian Rocks map. Builds the card DOM
 * exclusively with createElement/textContent — tile feature properties are
 * untrusted input, so no HTML interpolation — and lays out responsively via
 * Tailwind classes inside the map container: bottom sheet below the lg
 * breakpoint, docked panel at and above it. All static strings arrive localized from Rails via
 * the data-map-card-strings-value JSON blob.
 */

const CONTAINER_CLASSES = "absolute inset-x-0 bottom-0 z-20 max-h-[60vh] overflow-y-auto rounded-t-xl bg-white shadow-2xl lg:inset-x-auto lg:bottom-auto lg:left-4 lg:top-4 lg:w-96 lg:max-h-[calc(100%_-_2rem)] lg:rounded-xl"

export default class InfoCard {
    /**
     * @param {HTMLElement} container Stimulus card target element.
     * @param {Object} strings Parsed data-map-card-strings-value JSON.
     * @param {string} locale Active locale ("de" or "en").
     */
    constructor(container, strings, locale) {
        this.container = container
        this.strings = strings
        this.locale = locale
    }

    /**
     * Renders and shows the card for one selected feature.
     * @param {string} kind One of region/cluster/area/poi/problem.
     * @param {Object} properties Tile feature properties (untrusted).
     * @param {Object} callbacks { showOnMap, close } handlers.
     * @returns {void}
     */
    show(kind, properties, callbacks) {
        this.container.replaceChildren()
        this.container.className = CONTAINER_CLASSES

        if (kind === "problem") {
            this.container.appendChild(this.problemContent(properties, callbacks))
        } else if (kind === "poi") {
            this.container.appendChild(this.poiContent(properties, callbacks))
        } else {
            this.container.appendChild(this.entityContent(properties, callbacks))
        }
    }

    /**
     * Hides the card and drops its content.
     * @returns {void}
     */
    hide() {
        this.container.replaceChildren()
        this.container.className = "hidden"
    }

    /**
     * Builds the region/cluster/area card body.
     * @param {Object} properties Tile feature properties.
     * @param {Object} callbacks { showOnMap, close } handlers.
     * @returns {HTMLElement} Card body element.
     */
    entityContent(properties, callbacks) {
        const body = document.createElement("div")

        const coverUrl = this.safeHttpUrl(properties.coverPhotoUrl)
        if (coverUrl) {
            const media = document.createElement("div")
            media.className = "relative h-40 bg-gray-100"
            const cover = document.createElement("img")
            cover.src = coverUrl.toString()
            cover.alt = ""
            cover.className = "h-full w-full object-cover rounded-t-xl"
            cover.onerror = () => cover.remove()
            media.appendChild(cover)
            media.appendChild(this.mediaCloseButton(callbacks))
            body.appendChild(media)
        }

        const content = document.createElement("div")
        content.className = "p-4 space-y-3"
        content.appendChild(this.headerRow(this.localizedText(properties.name, properties.nameEn), callbacks, { showClose: !coverUrl }))

        const stats = this.statsLine(properties)
        if (stats) content.appendChild(stats)

        const warning = this.localizedText(properties.warning, properties.warningEn)
        if (warning) {
            const block = document.createElement("p")
            block.className = "rounded-lg bg-amber-50 p-3 text-sm text-amber-800"
            const label = document.createElement("span")
            label.className = "font-semibold"
            label.textContent = `${this.strings.warning}: `
            block.appendChild(label)
            block.appendChild(document.createTextNode(warning))
            content.appendChild(block)
        }

        const guidebookUrl = this.safeHttpUrl(properties.guidebookUrl)
        if (guidebookUrl && properties.guidebookTitle) {
            const title = properties.guidebookAuthor
                ? `${properties.guidebookTitle} — ${properties.guidebookAuthor}`
                : properties.guidebookTitle
            content.appendChild(this.labelledLinkRow(this.strings.guidebook, title, guidebookUrl))
        }

        const parkingUrl = this.safeHttpUrl(properties.parkingGoogleUrl)
        if (parkingUrl) {
            content.appendChild(this.labelledLinkRow(properties.parkingName || "", this.strings.directions, parkingUrl))
        }

        const button = document.createElement("button")
        button.type = "button"
        button.className = "w-full rounded-lg bg-brand-500 px-4 py-2 text-sm font-semibold text-white hover:bg-brand-600"
        button.textContent = this.strings.show_on_map
        button.addEventListener("click", () => callbacks.showOnMap())
        content.appendChild(button)

        body.appendChild(content)
        return body
    }

    /**
     * Builds the problem card body.
     * @param {Object} properties Tile feature properties.
     * @param {Object} callbacks { showOnMap, close } handlers.
     * @returns {HTMLElement} Card body element.
     */
    problemContent(properties, callbacks) {
        const body = document.createElement("div")
        const preview = this.problemTopoPreview(properties, callbacks)
        if (preview) body.appendChild(preview)

        const content = document.createElement("div")
        content.className = "p-4 space-y-3"
        content.appendChild(this.headerRow(this.localizedText(properties.name, properties.nameEn), callbacks, { showClose: !preview }))

        const details = this.problemDetails(properties)
        if (details) content.appendChild(details)

        const problemId = properties.problemId
        if (problemId !== undefined && problemId !== null && problemId !== "") {
            const cta = document.createElement("a")
            cta.href = `/${this.locale}/redirects/new?problem_id=${encodeURIComponent(problemId)}`
            cta.target = "_blank"
            cta.rel = "noopener noreferrer"
            cta.className = "block w-full rounded-lg bg-brand-500 px-4 py-2 text-center text-sm font-semibold text-white hover:bg-brand-600"
            cta.textContent = this.strings.details
            content.appendChild(cta)
        }

        body.appendChild(content)
        return body
    }

    /**
     * Builds a topo photo preview with the problem line overlay when tile data
     * carries both a safe photo URL and normalized line coordinates.
     * @param {Object} properties Tile feature properties.
     * @param {Object} callbacks { close } handler.
     * @returns {HTMLElement|null} Preview element or null.
     */
    problemTopoPreview(properties, callbacks) {
        const photoUrl = this.safeHttpUrl(properties.topoPhotoUrl)
        const coordinates = this.lineCoordinates(properties.lineCoordinatesJson)
        if (!photoUrl || coordinates.length < 2) return null

        const frame = document.createElement("div")
        frame.className = "relative overflow-hidden bg-gray-100 lg:rounded-t-xl"
        frame.style.aspectRatio = "4 / 3"

        const image = document.createElement("img")
        image.src = photoUrl.toString()
        image.alt = ""
        image.className = "h-full w-full object-cover"
        image.onerror = () => frame.remove()
        frame.appendChild(image)

        const svg = document.createElementNS("http://www.w3.org/2000/svg", "svg")
        svg.setAttribute("viewBox", "0 0 400 300")
        svg.setAttribute("preserveAspectRatio", "none")
        svg.setAttribute("class", "absolute inset-0 h-full w-full")

        const shadow = document.createElementNS("http://www.w3.org/2000/svg", "polyline")
        shadow.setAttribute("points", this.svgPoints(coordinates))
        shadow.setAttribute("fill", "none")
        shadow.setAttribute("stroke", "rgba(0,0,0,0.55)")
        shadow.setAttribute("stroke-width", "4")
        shadow.setAttribute("stroke-linecap", "round")
        shadow.setAttribute("stroke-linejoin", "round")
        svg.appendChild(shadow)

        const line = document.createElementNS("http://www.w3.org/2000/svg", "polyline")
        line.setAttribute("points", this.svgPoints(coordinates))
        line.setAttribute("fill", "none")
        line.setAttribute("stroke", "#ef3340")
        line.setAttribute("stroke-width", "2.4")
        line.setAttribute("stroke-linecap", "round")
        line.setAttribute("stroke-linejoin", "round")
        svg.appendChild(line)

        const start = coordinates[0]
        const dot = document.createElementNS("http://www.w3.org/2000/svg", "circle")
        dot.setAttribute("cx", String(start.x * 400))
        dot.setAttribute("cy", String(start.y * 300))
        dot.setAttribute("r", "7.5")
        dot.setAttribute("fill", "#ef3340")
        dot.setAttribute("stroke", "#ffffff")
        dot.setAttribute("stroke-width", "1")
        svg.appendChild(dot)

        frame.appendChild(svg)
        frame.appendChild(this.mediaCloseButton(callbacks))
        return frame
    }

    /**
     * Builds a more prominent problem grade row with secondary details beside it.
     * @param {Object} properties Tile feature properties.
     * @returns {HTMLElement|null} Details row or null.
     */
    problemDetails(properties) {
        const details = []
        const steepness = this.strings.steepness?.[properties.steepness]
        if (steepness) details.push(steepness)
        if (properties.height) details.push(this.strings.height_meters.replace("%{height}", properties.height))
        if (!properties.grade && details.length === 0) return null

        const row = document.createElement("div")
        row.className = "flex items-center gap-3"

        if (properties.grade) {
            const grade = document.createElement("span")
            grade.className = "text-3xl font-bold leading-none text-gray-700"
            grade.textContent = properties.grade
            row.appendChild(grade)
        }

        if (details.length > 0) {
            const meta = document.createElement("p")
            meta.className = "text-sm text-gray-500"
            meta.textContent = details.join(" · ")
            row.appendChild(meta)
        }

        return row
    }

    /**
     * Parses normalized line coordinates from a tile scalar JSON string.
     * @param {string} value JSON-encoded [{x, y}, ...] coordinates.
     * @returns {Object[]} Safe normalized coordinates.
     */
    lineCoordinates(value) {
        try {
            const coordinates = JSON.parse(value)
            if (!Array.isArray(coordinates)) return []

            return coordinates.filter((point) => {
                const x = Number(point?.x)
                const y = Number(point?.y)
                return Number.isFinite(x) && Number.isFinite(y) && x >= 0 && x <= 1 && y >= 0 && y <= 1
            }).map((point) => ({ x: Number(point.x), y: Number(point.y) }))
        } catch (_error) {
            return []
        }
    }

    /**
     * Converts normalized coordinates to SVG polyline points.
     * @param {Object[]} coordinates Safe normalized coordinates.
     * @returns {string} SVG points value.
     */
    svgPoints(coordinates) {
        return coordinates.map((point) => `${point.x * 400},${point.y * 300}`).join(" ")
    }

    /**
     * Builds the POI card body.
     * @param {Object} properties Tile feature properties.
     * @param {Object} callbacks { showOnMap, close } handlers.
     * @returns {HTMLElement} Card body element.
     */
    poiContent(properties, callbacks) {
        const content = document.createElement("div")
        content.className = "p-4 space-y-3"
        content.appendChild(this.headerRow(properties.name || "", callbacks))

        const poiType = this.strings.poi_types?.[properties.poiType]
        if (poiType) {
            const line = document.createElement("p")
            line.className = "text-sm text-gray-500"
            line.textContent = poiType
            content.appendChild(line)
        }

        const googleUrl = this.safeHttpUrl(properties.googleUrl)
        if (googleUrl) {
            content.appendChild(this.outboundLink(this.strings.directions, googleUrl, "block w-full rounded-lg bg-brand-500 px-4 py-2 text-center text-sm font-semibold text-white hover:bg-brand-600"))
        }

        return content
    }

    /**
     * Builds the title row with the close button.
     * @param {string} title Localized display name.
     * @param {Object} callbacks { showOnMap, close } handlers.
     * @returns {HTMLElement} Header row element.
     */
    headerRow(title, callbacks, { showClose = true } = {}) {
        const row = document.createElement("div")
        row.className = "flex items-start justify-between gap-2"

        const heading = document.createElement("h2")
        heading.className = "text-lg font-semibold text-gray-900"
        heading.textContent = title
        row.appendChild(heading)

        if (showClose) row.appendChild(this.headerCloseButton(callbacks))
        return row
    }

    /**
     * Builds a normal close button for non-media card headers.
     * @param {Object} callbacks { close } handler.
     * @returns {HTMLElement} Close button.
     */
    headerCloseButton(callbacks) {
        const close = document.createElement("button")
        close.type = "button"
        close.className = "inline-flex h-8 w-8 shrink-0 items-center justify-center rounded-full text-gray-400 hover:bg-gray-100 hover:text-gray-600"
        close.setAttribute("aria-label", this.strings.close)
        close.textContent = "✕"
        close.addEventListener("click", () => callbacks.close())
        return close
    }

    /**
     * Builds a high-contrast close button over photo/topo media.
     * @param {Object} callbacks { close } handler.
     * @returns {HTMLElement} Close button.
     */
    mediaCloseButton(callbacks) {
        const close = document.createElement("button")
        close.type = "button"
        close.className = "absolute right-3 top-3 z-10 inline-flex h-8 w-8 items-center justify-center rounded-full bg-black/55 font-semibold leading-none text-white shadow-lg ring-1 ring-white/40 backdrop-blur-sm hover:bg-black/70 focus:outline-none focus:ring-2 focus:ring-white"
        close.setAttribute("aria-label", this.strings.close)
        close.textContent = "✕"
        close.addEventListener("click", () => callbacks.close())
        return close
    }

    /**
     * Builds the problem-count line and grade-distribution histogram when data
     * is present. Tiles published before the histogram property exist fall back
     * to the textual grade range.
     * @param {Object} properties Tile feature properties.
     * @returns {HTMLElement|null} Stats block element or null.
     */
    statsLine(properties) {
        const histogram = this.gradeHistogram(properties.gradeHistogramJson)

        const parts = []
        if (properties.problemCount !== undefined && properties.problemCount !== null) {
            parts.push(`${properties.problemCount} ${this.strings.problems}`)
        }
        if (!histogram && properties.gradeMin && properties.gradeMax) {
            parts.push(`${properties.gradeMin} – ${properties.gradeMax}`)
        }
        if (parts.length === 0 && !histogram) return null

        const block = document.createElement("div")
        block.className = "space-y-4"
        if (parts.length > 0) {
            const line = document.createElement("p")
            line.className = "text-sm text-gray-500"
            line.textContent = parts.join(" · ")
            block.appendChild(line)
        }
        if (histogram) block.appendChild(histogram)
        return block
    }

    /**
     * Builds the grade-distribution bar chart from the tile histogram property.
     * One column per letter grade ("6a", "6b", …), trimmed to the populated
     * range (padded to at least five columns so bars keep a consistent width);
     * bar heights scale to the most common grade. Hovering a column shows its
     * problem count in a small bubble.
     * @param {string} value JSON-encoded per-letter-grade problem counts.
     * @returns {HTMLElement|null} Histogram element or null.
     */
    gradeHistogram(value) {
        const entries = this.histogramEntries(value)
        if (!entries) return null

        const max = Math.max(...entries.map(({ count }) => count))

        const chart = document.createElement("div")
        chart.className = "pt-4 pb-3"
        chart.setAttribute("role", "img")
        chart.setAttribute(
            "aria-label",
            `${this.strings.grade_distribution}: ${entries.map(({ grade, count }) => `${grade}: ${count}`).join(", ")}`,
        )

        const bars = document.createElement("div")
        bars.className = "flex h-12 items-stretch gap-px border-b border-gray-200"
        const labels = document.createElement("div")
        labels.className = "mt-2 flex gap-px"

        for (const { grade, count } of entries) {
            const column = document.createElement("div")
            column.className = "group relative flex flex-1 items-end"
            column.title = `${grade}: ${count} ${this.strings.problems}`

            const bar = document.createElement("div")
            bar.className = `w-full rounded-t-sm ${this.histogramBarColor(count, max)}`
            bar.style.height = count > 0 ? `${Math.max(4, Math.round((count / max) * 48))}px` : "2px"
            column.appendChild(bar)

            if (count > 0) {
                const bubble = document.createElement("span")
                bubble.className = "pointer-events-none absolute left-1/2 hidden -translate-x-1/2 whitespace-nowrap rounded bg-gray-900/80 px-1 py-0.5 text-[10px] font-medium leading-none text-white group-hover:block"
                bubble.style.bottom = `${Math.max(4, Math.round((count / max) * 48)) + 3}px`
                bubble.textContent = String(count)
                column.appendChild(bubble)
            }
            bars.appendChild(column)

            const label = document.createElement("span")
            label.className = "flex-1 text-center text-[10px] font-medium leading-none text-gray-400"
            label.textContent = grade
            labels.appendChild(label)
        }

        chart.appendChild(bars)
        chart.appendChild(labels)
        return chart
    }

    /**
     * Picks the bar color tier from the count relative to the most common
     * grade: the busiest third renders most intense, quieter grades fade.
     * @param {number} count Problems at this grade.
     * @param {number} max Problems at the most common grade.
     * @returns {string} Tailwind background class.
     */
    histogramBarColor(count, max) {
        if (count <= 0) return "bg-gray-200"
        const ratio = count / max
        if (ratio > 2 / 3) return "bg-brand-500"
        if (ratio > 1 / 3) return "bg-brand-400"
        return "bg-brand-300"
    }

    /**
     * Parses the per-letter-grade histogram from a tile scalar JSON string into
     * an ordered, gap-filled list of {grade, count} entries trimmed to the
     * populated range (padded to at least five columns).
     * @param {string} value JSON-encoded {"6a": 12, ...} object.
     * @returns {Object[]|null} Safe ordered entries or null.
     */
    histogramEntries(value) {
        let counts
        try {
            counts = JSON.parse(value)
        } catch (_error) {
            return null
        }
        if (typeof counts !== "object" || counts === null || Array.isArray(counts)) return null

        const scale = []
        for (let level = 1; level <= 9; level += 1) {
            for (const letter of ["a", "b", "c"]) scale.push(`${level}${letter}`)
        }
        const valid = Object.entries(counts).every(([grade, count]) =>
            scale.includes(grade) && Number.isInteger(count) && count > 0)
        if (!valid || Object.keys(counts).length === 0) return null

        let first = scale.findIndex((grade) => counts[grade])
        let last = scale.length - 1 - [...scale].reverse().findIndex((grade) => counts[grade])
        const MIN_COLUMNS = 5
        while (last - first + 1 < MIN_COLUMNS && (first > 0 || last < scale.length - 1)) {
            if (last < scale.length - 1) last += 1
            else first -= 1
        }

        return scale.slice(first, last + 1).map((grade) => ({ grade, count: counts[grade] || 0 }))
    }

    /**
     * Builds a label + outbound-link row.
     * @param {string} label Row label text.
     * @param {string} linkText Link text.
     * @param {URL} url Verified HTTP(S) URL.
     * @returns {HTMLElement} Row element.
     */
    labelledLinkRow(label, linkText, url) {
        const row = document.createElement("p")
        row.className = "text-sm text-gray-700"
        if (label) row.appendChild(document.createTextNode(`${label}: `))
        row.appendChild(this.outboundLink(linkText, url, "font-medium text-brand-500 hover:underline"))
        return row
    }

    /**
     * Builds a safe outbound link.
     * @param {string} text Link text.
     * @param {URL} url Verified HTTP(S) URL.
     * @param {string} className Tailwind classes for the link.
     * @returns {HTMLElement} Anchor element.
     */
    outboundLink(text, url, className) {
        const link = document.createElement("a")
        link.href = url.toString()
        link.target = "_blank"
        link.rel = "noopener noreferrer"
        link.className = className
        link.textContent = text
        return link
    }

    /**
     * Selects the localized value following the tile contract (base value is
     * German, the En variant is present only when different).
     * @param {string} value German/base value.
     * @param {string} valueEn English variant or undefined.
     * @returns {string} Localized text.
     */
    localizedText(value, valueEn) {
        if (this.locale === "en" && valueEn) return valueEn
        return value || ""
    }

    /**
     * Accepts only HTTP(S) URLs for card links.
     * @param {string} value Raw URL value from tile properties.
     * @returns {URL|null} Parsed safe URL or null.
     */
    safeHttpUrl(value) {
        try {
            const url = new URL(value)
            return ["http:", "https:"].includes(url.protocol) ? url : null
        } catch (_error) {
            return null
        }
    }
}

/**
 * Selection state machine for the Austrian Rocks map: at most one feature is
 * selected at any time, ever — selecting while something else is selected
 * clears the previous selection first.
 *
 * Selection is rendered through dedicated single-feature `-selected` style
 * layers filtered by entity id (sentinel -1 when cleared) instead of MapLibre
 * `feature-state`, because the same filter mechanism works identically in
 * MapLibre GL JS and MapLibre Native, keeping web and the future mobile apps
 * on one shared style/tile contract. The selected id is also excluded from
 * the base symbol layer's filter so the resting pin does not render
 * underneath the selected balloon.
 */

const CLEARED_SENTINEL = -1
const GROW_DURATION_MS = 520
const CLEAR_DURATION_MS = 220
const ICON_GROW_SCALE = 1.25
const ICON_CLEAR_SCALE = 0.72
const CIRCLE_GROW_SCALE = 1.4
const CIRCLE_CLEAR_SCALE = 1
const ICON_SETTLE_OVERSHOOT = 0.1
const CIRCLE_SETTLE_OVERSHOOT = 0.08
const ICON_WIGGLE_DEGREES = 5

const SELECTABLE_KINDS = {
    region: { selectedLayerId: "regions-selected", baseLayerId: "regions", idProperty: "regionId" },
    cluster: { selectedLayerId: "clusters-selected", baseLayerId: "clusters", idProperty: "clusterId" },
    area: { selectedLayerId: "areas-selected", baseLayerId: "areas", idProperty: "areaId" },
    poi: { selectedLayerId: "pois-selected", baseLayerId: "pois", idProperty: "poiId" },
    // The base problems layer keeps its grade filter (owned by the map
    // controller's filter UI) and the bigger stroked selected circle fully
    // covers the base circle, so problems skip the base-layer exclusion.
    problem: { selectedLayerId: "problems-selected", baseLayerId: null, idProperty: "problemId", circle: true },
}

export default class MapSelection {
    /**
     * @param {maplibregl.Map} map Loaded MapLibre map with the shared style.
     */
    constructor(map) {
        this.map = map
        this.current = null
        this.growFrame = null
        this.originalBaseFilters = new Map()
        this.originalGrowValues = new Map()
        this.originalIconRotations = new Map()
    }

    /**
     * Selects one feature by entity kind and id, replacing any prior selection.
     * @param {string} kind One of region/cluster/area/poi/problem.
     * @param {number} id Entity id baked into the tile properties.
     * @returns {void}
     */
    select(kind, id) {
        const config = SELECTABLE_KINDS[kind]
        if (!config || !this.map.getLayer(config.selectedLayerId)) return
        if (this.current) this.clear({ animated: false })

        this.map.setFilter(config.selectedLayerId, ["==", ["get", config.idProperty], id])
        this.excludeFromBaseLayer(config, id)
        this.current = { kind, id, layerId: config.selectedLayerId }
        this.startGrowTween(config)
    }

    /**
     * Clears the current selection and restores all touched layer state.
     * @param {Object} options Clear options.
     * @param {boolean} options.animated Whether to play the selected→resting shrink.
     * @returns {void}
     */
    clear({ animated = true } = {}) {
        if (!this.current) return

        const current = this.current
        const config = SELECTABLE_KINDS[current.kind]
        this.cancelGrowTween()

        if (animated) {
            this.startClearTween(config, () => this.finishClear(config, current))
        } else {
            this.finishClear(config, current)
        }
    }

    /**
     * Finalizes clearing after the optional shrink animation.
     * @param {Object} config Selectable kind configuration.
     * @param {Object} current Selection being cleared.
     * @returns {void}
     */
    finishClear(config, current) {
        if (this.current !== current) return

        this.applyGrowScale(config, 1)
        this.restoreIconRotation(config)
        this.map.setFilter(config.selectedLayerId, ["==", ["get", config.idProperty], CLEARED_SENTINEL])
        this.restoreBaseLayer(config)
        this.current = null
    }

    /**
     * Hides the selected feature's resting pin by excluding its id from the
     * base symbol layer's filter.
     * @param {Object} config Selectable kind configuration.
     * @param {number} id Selected entity id.
     * @returns {void}
     */
    excludeFromBaseLayer(config, id) {
        if (!config.baseLayerId || !this.map.getLayer(config.baseLayerId)) return

        if (!this.originalBaseFilters.has(config.baseLayerId)) {
            this.originalBaseFilters.set(config.baseLayerId, this.map.getFilter(config.baseLayerId))
        }

        const exclusion = ["!=", ["get", config.idProperty], id]
        const original = this.originalBaseFilters.get(config.baseLayerId)
        this.map.setFilter(config.baseLayerId, original ? ["all", original, exclusion] : exclusion)
    }

    /**
     * Restores the base symbol layer's original filter after deselection.
     * @param {Object} config Selectable kind configuration.
     * @returns {void}
     */
    restoreBaseLayer(config) {
        if (!config.baseLayerId || !this.originalBaseFilters.has(config.baseLayerId)) return

        this.map.setFilter(config.baseLayerId, this.originalBaseFilters.get(config.baseLayerId))
    }

    /**
     * Runs a quick grow + settle tween on the selected layer.
     * @param {Object} config Selectable kind configuration.
     * @returns {void}
     */
    startGrowTween(config) {
        this.cancelGrowTween()

        const targetScale = config.circle ? CIRCLE_GROW_SCALE : ICON_GROW_SCALE
        const overshoot = config.circle ? CIRCLE_SETTLE_OVERSHOOT : ICON_SETTLE_OVERSHOOT
        const start = performance.now()
        const step = (now) => {
            const progress = Math.min((now - start) / GROW_DURATION_MS, 1)
            this.applySelectionFrame(config, this.settleScale(progress, targetScale, overshoot), progress)
            this.growFrame = progress < 1 ? requestAnimationFrame(step) : null
        }
        this.growFrame = requestAnimationFrame(step)
    }

    /**
     * Runs the selected→resting shrink before the selected layer is hidden.
     * @param {Object} config Selectable kind configuration.
     * @param {Function} finish Called after the animation completes.
     * @returns {void}
     */
    startClearTween(config, finish) {
        const startScale = config.circle ? CIRCLE_GROW_SCALE : ICON_GROW_SCALE
        const endScale = config.circle ? CIRCLE_CLEAR_SCALE : ICON_CLEAR_SCALE
        const start = performance.now()
        const step = (now) => {
            const progress = Math.min((now - start) / CLEAR_DURATION_MS, 1)
            const eased = 1 - Math.pow(1 - progress, 3)
            this.applySelectionFrame(config, startScale + (endScale - startScale) * eased, 1)
            if (progress < 1) {
                this.growFrame = requestAnimationFrame(step)
            } else {
                this.growFrame = null
                finish()
            }
        }
        this.growFrame = requestAnimationFrame(step)
    }

    /**
     * Eases past the final grow size, then gently settles back for a
     * lightweight Apple-Maps-like selection pop without a distracting bounce.
     * @param {number} progress Tween progress, clamped 0..1.
     * @param {number} targetScale Final scale factor.
     * @param {number} overshoot Extra scale at the peak.
     * @returns {number} Current scale factor.
     */
    settleScale(progress, targetScale, overshoot) {
        if (progress < 0.55) {
            const eased = 1 - Math.pow(1 - (progress / 0.55), 3)
            return 1 + ((targetScale + overshoot) - 1) * eased
        }

        const settle = (progress - 0.55) / 0.45
        const wave = Math.sin(settle * Math.PI * 2) * (1 - settle) * (overshoot * 0.55)
        return targetScale + wave
    }

    /**
     * Cancels a running grow tween frame, if any.
     * @returns {void}
     */
    cancelGrowTween() {
        if (this.growFrame == null) return

        cancelAnimationFrame(this.growFrame)
        this.growFrame = null
    }

    /**
     * Applies one animation frame: icon-size + a subtle rotation wiggle for
     * symbol layers, circle-radius for the selected problems circle layer.
     * @param {Object} config Selectable kind configuration.
     * @param {number} scale Current scale factor (1 = resting style value).
     * @param {number} progress Tween progress, clamped 0..1.
     * @returns {void}
     */
    applySelectionFrame(config, scale, progress) {
        this.applyGrowScale(config, scale)
        if (!config.circle) this.applyIconWiggle(config, progress)
    }

    /**
     * Applies one grow-tween scale step: icon-size for symbol layers,
     * circle-radius for the selected problems circle layer.
     * @param {Object} config Selectable kind configuration.
     * @param {number} scale Current scale factor (1 = resting style value).
     * @returns {void}
     */
    applyGrowScale(config, scale) {
        if (!this.map.getLayer(config.selectedLayerId)) return

        if (config.circle) {
            const base = this.originalGrowValue(config, () => this.map.getPaintProperty(config.selectedLayerId, "circle-radius"))
            this.map.setPaintProperty(config.selectedLayerId, "circle-radius", this.scaledValue(base, scale))
        } else {
            const base = this.originalGrowValue(config, () => this.map.getLayoutProperty(config.selectedLayerId, "icon-size") ?? 1)
            this.map.setLayoutProperty(config.selectedLayerId, "icon-size", this.scaledValue(base, scale))
        }
    }

    /**
     * Adds a tiny damped rotation wiggle to selected symbol layers. MapLibre
     * rotates the icon around its anchor, so the selected balloon pivots around
     * the pin's location dot instead of around the sprite center.
     * @param {Object} config Selectable kind configuration.
     * @param {number} progress Tween progress, clamped 0..1.
     * @returns {void}
     */
    applyIconWiggle(config, progress) {
        if (!this.map.getLayer(config.selectedLayerId)) return

        const base = this.originalIconRotation(config)
        const easedProgress = 1 - Math.pow(1 - progress, 2)
        const amplitude = ICON_WIGGLE_DEGREES * Math.max(0, 1 - easedProgress)
        const rotation = base + (Math.sin(easedProgress * Math.PI * 2.5) * amplitude)
        this.map.setLayoutProperty(config.selectedLayerId, "icon-rotate", rotation)
    }

    /**
     * Restores the selected symbol layer's style-declared icon rotation.
     * @param {Object} config Selectable kind configuration.
     * @returns {void}
     */
    restoreIconRotation(config) {
        if (config.circle || !this.originalIconRotations.has(config.selectedLayerId)) return

        this.map.setLayoutProperty(config.selectedLayerId, "icon-rotate", this.originalIconRotations.get(config.selectedLayerId))
    }

    /**
     * Returns the layer's style-declared grow-property value, captured once
     * before the first tween mutates it.
     * @param {Object} config Selectable kind configuration.
     * @param {Function} read Reads the current style value for the property.
     * @returns {number|Array} Original style value.
     */
    originalGrowValue(config, read) {
        if (!this.originalGrowValues.has(config.selectedLayerId)) {
            this.originalGrowValues.set(config.selectedLayerId, read())
        }
        return this.originalGrowValues.get(config.selectedLayerId)
    }

    /**
     * Returns the style-declared icon rotation for a selected symbol layer.
     * @param {Object} config Selectable kind configuration.
     * @returns {number} Original icon rotation.
     */
    originalIconRotation(config) {
        if (!this.originalIconRotations.has(config.selectedLayerId)) {
            this.originalIconRotations.set(config.selectedLayerId, this.map.getLayoutProperty(config.selectedLayerId, "icon-rotate") || 0)
        }
        return this.originalIconRotations.get(config.selectedLayerId)
    }

    /**
     * Scales a numeric style value directly or wraps an expression in "*".
     * @param {number|Array} value Original style value or expression.
     * @param {number} scale Scale factor.
     * @returns {number|Array} Scaled style value.
     */
    scaledValue(value, scale) {
        if (scale === 1) return value
        if (typeof value === "number") return value * scale
        return ["*", scale, value]
    }
}

/**
 * Stimulus controller for the Rails map pages. It wires MapLibre GL JS, the
 * PMTiles protocol, release-manifest style loading, web-only interactions,
 * pin selection with the responsive info card, grade filters, search events,
 * and the dynamic contribution-request overlay; shared basemap/source/layer
 * styling lives in the published style JSONs.
 */
import { Controller } from "@hotwired/stimulus"
import maplibregl from "maplibre-gl"
import { Protocol } from "pmtiles"
import MapSelection from "map/selection"
import InfoCard from "map/info_card"

const AUSTRIA_BOUNDS = [
    [9.430320338084726, 46.28576190178245],
    [17.230613306834925, 49.18126637161225],
]
const AUSTRIA_MAX_BOUNDS = [
    [8.75, 45.7],
    [17.95, 49.75],
]
const GRADE_FILTER_LAYERS = ["problems"]
const ALL_GRADES = [
    "1a", "1a/+", "1a+", "1b", "1b/+", "1b+", "1c", "1c/+", "1c+",
    "2a", "2a/+", "2a+", "2b", "2b/+", "2b+", "2c", "2c/+", "2c+",
    "3a", "3a/+", "3a+", "3b", "3b/+", "3b+", "3c", "3c/+", "3c+",
    "4a", "4a/+", "4a+", "4b", "4b/+", "4b+", "4c", "4c/+", "4c+",
    "5a", "5a/+", "5a+", "5b", "5b/+", "5b+", "5c", "5c/+", "5c+",
    "6a", "6a/+", "6a+", "6b", "6b/+", "6b+", "6c", "6c/+", "6c+",
    "7a", "7a/+", "7a+", "7b", "7b/+", "7b+", "7c", "7c/+", "7c+",
    "8a", "8a/+", "8a+", "8b", "8b/+", "8b+", "8c", "8c/+", "8c+",
    "9a", "9a/+", "9a+", "9b", "9b/+", "9b+", "9c", "9c/+", "9c+",
]

export default class extends Controller {
    static targets = [
        "map",
        "card",
        "gradeRadioButton",
        "gradeMin",
        "gradeMax",
        "customGradePicker",
        "filterCounter",
        "filterIcon",
    ]

    static values = {
        bounds: Object,
        problem: Object,
        cardStrings: Object,
        areaId: Number,
        locale: { type: String, default: "en" },
        manifestUrl: String,
        style: { type: String, default: "light" },
        contribute: { type: Boolean, default: false },
        contributeSource: String,
    }

    /**
     * Registers the PMTiles protocol, loads the release manifest, and creates
     * the MapLibre map once Stimulus connects the controller.
     * @returns {Promise<void>}
     */
    async connect() {
        this.allGrades = ALL_GRADES
        this.protocol = new Protocol()
        maplibregl.addProtocol("pmtiles", this.protocol.tile)

        try {
            const styleUrl = await this.loadStyleUrl()
            this.initializeMap(styleUrl)
        } catch (error) {
            console.error("Could not initialize Austrian Rocks map", error)
        }
    }

    /**
     * Removes the map and unregisters PMTiles when Turbo disconnects the page.
     * @returns {void}
     */
    disconnect() {
        if (this.map) {
            this.map.remove()
            this.map = null
        }

        if (maplibregl.removeProtocol) {
            maplibregl.removeProtocol("pmtiles")
        }
    }

    /**
     * Fetches the non-cached release manifest and selects the configured style.
     * @returns {Promise<string>} Versioned MapLibre style URL.
     */
    async loadStyleUrl() {
        const response = await fetch(this.manifestUrlValue, {
            cache: "no-store",
            credentials: "same-origin",
        })
        if (!response.ok) {
            throw new Error(`Map release manifest failed with ${response.status}`)
        }

        const manifest = await response.json()
        const styles = manifest.styles || {}
        const styleName = this.styleValue || "light"
        const styleUrl = styles[styleName]
        if (!styleUrl) {
            throw new Error(`Map release manifest is missing the ${styleName} style`)
        }

        return styleUrl
    }

    /**
     * Creates the MapLibre map and wires load/move/click behaviour.
     * @param {string} styleUrl Versioned style JSON URL from the manifest.
     * @returns {void}
     */
    initializeMap(styleUrl) {
        this.map = new maplibregl.Map({
            container: this.mapTarget,
            locale: this.localeValue == "de" ? this.getDeLocale() : undefined,
            hash: true,
            style: styleUrl,
            bounds: AUSTRIA_BOUNDS,
            maxBounds: AUSTRIA_MAX_BOUNDS,
            padding: 5,
        })

        this.addControls()

        this.map.on("load", () => {
            this.constrainMinimumZoom()
            this.selection = new MapSelection(this.map)
            if (this.hasCardTarget) {
                this.infoCard = new InfoCard(this.cardTarget, this.cardStringsValue, this.localeValue)
            }
            this.addContributionLayers()
            this.centerMap()
            this.cleanHistory()
            this.setupClickEvents()
        })
    }

    /**
     * Prevents zooming out so far that Austria becomes a small island, while
     * keeping a padded max-bounds envelope for easy border-region exploration.
     * @returns {void}
     */
    constrainMinimumZoom() {
        const camera = this.map.cameraForBounds(AUSTRIA_MAX_BOUNDS, { padding: 20 })
        if (camera?.zoom !== undefined) this.map.setMinZoom(camera.zoom)
    }

    /**
     * Adds scale, navigation, and geolocation controls.
     * @returns {void}
     */
    addControls() {
        this.map.addControl(new maplibregl.ScaleControl({ maxWidth: 100, unit: "metric" }))
        this.map.addControl(new maplibregl.NavigationControl())
        this.map.addControl(new maplibregl.GeolocateControl({
            positionOptions: { enableHighAccuracy: true },
            trackUserLocation: true,
            showUserHeading: true,
        }))
    }

    /**
     * Adds the web-only dynamic contribution-request GeoJSON source and layers.
     * @returns {void}
     */
    addContributionLayers() {
        if (!this.contributeValue || !this.hasContributeSourceValue) return

        this.map.addSource("contribute", {
            type: "geojson",
            data: this.contributeSourceValue,
        })

        this.map.addLayer({
            id: "contribute-problems",
            type: "circle",
            source: "contribute",
            layout: { visibility: "visible" },
            paint: {
                "circle-radius": [
                    "interpolate", ["linear"], ["zoom"],
                    12, 6,
                    17, 20,
                    18, 25,
                    19, 50,
                    20, 50,
                    21, 50,
                    22, 20,
                ],
                "circle-color": "#FFCC02",
                "circle-opacity": 0.25,
                "circle-stroke-width": 2,
                "circle-stroke-color": "white",
            },
            filter: ["match", ["geometry-type"], ["Point"], true, false],
        }, this.layerBefore("areas"))

        this.map.addLayer({
            id: "contribute-problems-texts",
            type: "symbol",
            source: "contribute",
            minzoom: 16,
            layout: {
                visibility: "visible",
                "text-allow-overlap": true,
                "text-field": ["to-string", ["get", "name"]],
                "text-font": ["Roboto-Regular"],
                "text-size": ["interpolate", ["linear"], ["zoom"], 19, 10, 22, 20],
            },
            paint: {
                "text-color": "#333",
                "text-halo-color": "hsl(0, 0%, 100%)",
                "text-halo-width": 1,
            },
            filter: ["match", ["geometry-type"], ["Point"], true, false],
        })
    }

    /**
     * Returns a layer insertion ID only when that style layer exists.
     * @param {string} layerId Candidate style layer ID.
     * @returns {string|undefined} Existing layer ID or undefined.
     */
    layerBefore(layerId) {
        return this.map.getLayer(layerId) ? layerId : undefined
    }

    /**
     * Centers the map on area bounds or a problem deep link supplied by Rails.
     * @returns {void}
     */
    centerMap() {
        if (this.hasBoundsValue) {
            const bounds = this.boundsValue
            this.flyToBounds([
                [bounds.southWestLon, bounds.southWestLat],
                [bounds.northEastLon, bounds.northEastLat],
            ])
            if (this.hasAreaIdValue) {
                this.selectFeatureWhenIdle("areas", "areaId", this.areaIdValue, "area")
            }
        }

        if (this.hasProblemValue) {
            const problem = this.problemValue
            this.map.flyTo({ center: [problem.lon, problem.lat], zoom: 20, speed: 2 })
            this.selectFeatureWhenIdle("problems", "problemId", problem.id, "problem")
        }
    }

    /**

[577 more lines in file. Use offset=261 to continue.]

     * Removes deep-link query parameters when the user starts moving the map.
     * @returns {void}
     */
    cleanHistory() {
        this.map.on("movestart", () => {
            const url = this.contributeValue ? `/${this.localeValue}/mapping/map` : `/${this.localeValue}/map`
            history.replaceState({}, "", url)
        })
    }

    /**
     * Wires cursor and click handlers for shared style layers and contribution layers.
     * @returns {void}
     */
    setupClickEvents() {
        this.registerPointerLayer("problems", (zoom) => zoom >= 15)
        this.registerPointerLayer("pois", (zoom) => zoom >= 12)
        this.registerPointerLayer("areas", (zoom) => zoom < 16)
        this.registerPointerLayer("areas-hulls", (zoom) => zoom < 15)
        this.registerPointerLayer("clusters", (zoom) => zoom <= 12)
        this.registerPointerLayer("cluster-hulls", (zoom) => zoom <= 12)
        this.registerPointerLayer("regions", (zoom) => zoom <= 10)
        this.registerPointerLayer("region-hulls", (zoom) => zoom <= 10)
        this.registerContributionClicks()
        this.registerSelectClicks("problems", "problem", (zoom) => zoom >= 15)
        this.registerSelectClicks("pois", "poi", (zoom) => zoom >= 12)
        this.registerSelectClicks("areas", "area", (zoom) => zoom < 16)
        this.registerSelectClicks("areas-hulls", "area", (zoom) => zoom < 15)
        this.registerSelectClicks("clusters", "cluster", (zoom) => zoom <= 12)
        this.registerSelectClicks("cluster-hulls", "cluster", (zoom) => zoom <= 12)
        this.registerSelectClicks("regions", "region", (zoom) => zoom <= 10)
        this.registerSelectClicks("region-hulls", "region", (zoom) => zoom <= 10)
        this.registerBackgroundClicks()
    }

    /**
     * Sets a pointer cursor for an interactive layer when its zoom predicate passes.
     * @param {string} layerId Layer ID to handle.
     * @param {Function} zoomPredicate Returns true when the cursor should be a pointer.
     * @returns {void}
     */
    registerPointerLayer(layerId, zoomPredicate = () => true) {
        if (!this.map.getLayer(layerId)) return

        this.map.on("mouseenter", layerId, () => {
            if (zoomPredicate(this.map.getZoom())) this.map.getCanvas().style.cursor = "pointer"
        })
        this.map.on("mouseleave", layerId, () => { this.map.getCanvas().style.cursor = "" })
    }

    /**
     * Selects the clicked feature and opens its info card.
     * @param {string} layerId Layer ID to handle (hulls select their pin's entity).
     * @param {string} kind Entity kind: region/cluster/area/poi/problem.
     * @param {Function} zoomPredicate Returns true when click should select.
     * @returns {void}
     */
    registerSelectClicks(layerId, kind, zoomPredicate = () => true) {
        if (!this.map.getLayer(layerId)) return

        this.map.on("click", layerId, (event) => {
            if (!zoomPredicate(this.map.getZoom())) return

            this.lastInteractiveClickEvent = event.originalEvent
            const feature = event.features[0]
            const id = feature.properties[`${kind}Id`]
            if (id === undefined || id === null) return
            if (this.selection.current?.kind === kind && this.selection.current?.id === id) return

            this.selectFeature(kind, id, feature.properties, event.lngLat)
        })
    }

    /**
     * Clears the selection when a click hits no interactive feature.
     * @returns {void}
     */
    registerBackgroundClicks() {
        this.map.on("click", (event) => {
            if (!this.selection.current) return
            if (event.originalEvent && event.originalEvent === this.lastInteractiveClickEvent) return

            const features = this.map.queryRenderedFeatures(event.point, {
                layers: this.interactiveLayerIds(),
            })
            if (features.length === 0) this.clearSelection()
        })
    }

    /**
     * Returns the existing layer IDs a click may interact with.
     * @returns {string[]} Existing interactive layer IDs.
     */
    interactiveLayerIds() {
        return [
            "problems", "problems-selected",
            "pois", "pois-selected",
            "areas", "areas-selected", "areas-hulls",
            "clusters", "clusters-selected", "cluster-hulls",
            "regions", "regions-selected", "region-hulls",
            "contribute-problems", "contribute-problems-texts",
        ].filter((layerId) => this.map.getLayer(layerId))
    }

    /**
     * After camera movement settles, finds a tile feature by id and selects it.
     * The source query handles off-screen tile data; rendered features are a
     * fallback for style-loaded features. Missing features are retried once and
     * then ignored so stale deep links never break the map.
     * @param {string} sourceLayer PMTiles source-layer name.
     * @param {string} idProperty Feature id property to filter by.
     * @param {number|string} id Feature id to select.
     * @param {string} kind Entity kind: region/cluster/area/poi/problem.
     * @param {number} attemptsRemaining Retry budget after this idle event.
     * @returns {void}
     */
    selectFeatureWhenIdle(sourceLayer, idProperty, id, kind, attemptsRemaining = 1) {
        if (id === undefined || id === null) return

        this.map.once("idle", () => {
            try {
                const filter = ["==", ["get", idProperty], id]
                const feature = this.findSelectableFeature(sourceLayer, kind, filter)
                if (feature) {
                    this.selectFeature(kind, id, feature.properties || {}, this.featureLngLat(feature))
                } else if (attemptsRemaining > 0) {
                    this.selectFeatureWhenIdle(sourceLayer, idProperty, id, kind, attemptsRemaining - 1)
                }
            } catch (_error) {
                // Deep-link/search selection is best-effort; leave the map usable.
            }
        })
    }

    /**
     * Finds a selectable feature from source tiles, falling back to rendered layers.
     * @param {string} sourceLayer PMTiles source-layer name.
     * @param {string} kind Entity kind used to choose rendered fallback layers.
     * @param {Array} filter MapLibre filter expression.
     * @returns {Object|undefined} First matching feature.
     */
    findSelectableFeature(sourceLayer, kind, filter) {
        const sourceFeatures = this.map.querySourceFeatures("austrian-rocks", { sourceLayer, filter })
        if (sourceFeatures.length > 0) return sourceFeatures[0]

        const layers = this.renderedLayersForKind(kind)
        if (layers.length === 0) return undefined

        return this.map.queryRenderedFeatures({ layers, filter })[0]
    }

    /**
     * Returns existing rendered layers for a feature kind.
     * @param {string} kind Entity kind: region/cluster/area/poi/problem.
     * @returns {string[]} Existing layer IDs.
     */
    renderedLayersForKind(kind) {
        const layerIds = {
            problem: ["problems", "problems-selected"],
            poi: ["pois", "pois-selected"],
            area: ["areas", "areas-selected", "areas-hulls"],
            cluster: ["clusters", "clusters-selected", "cluster-hulls"],
            region: ["regions", "regions-selected", "region-hulls"],
        }[kind] || []

        return layerIds.filter((layerId) => this.map.getLayer(layerId))
    }

    /**
     * Returns a representative coordinate for a feature to keep visible by the card.
     * @param {Object} feature MapLibre feature.
     * @returns {Array<number>|undefined} LngLat-like coordinate.
     */
    featureLngLat(feature) {
        if (feature.geometry?.type === "Point") return feature.geometry.coordinates.slice()

        const properties = feature.properties || {}
        const west = Number(properties.southWestLon)
        const east = Number(properties.northEastLon)
        const south = Number(properties.southWestLat)
        const north = Number(properties.northEastLat)
        if (![west, east, south, north].every(Number.isFinite)) return undefined

        return [
            (west + east) / 2,
            (south + north) / 2,
        ]
    }

    /**
     * Applies a selection: grows the selected pin and opens the info card.
     * @param {string} kind Entity kind: region/cluster/area/poi/problem.
     * @param {number} id Entity id from the tile properties.
     * @param {Object} properties Tile feature properties for the card.
     * @param {maplibregl.LngLatLike} lngLat Selected coordinate for sheet handling.
     * @returns {void}
     */
    selectFeature(kind, id, properties, lngLat) {
        this.selection.select(kind, id)
        this.infoCard?.show(kind, properties, {
            showOnMap: () => this.showSelectionOnMap(kind, properties),
            close: () => this.clearSelection(),
        })
        this.adjustSheetPadding(lngLat)
    }

    /**
     * Clears the selection and hides the card, leaving any user-visible camera
     * padding in place instead of snapping the map back on close.
     * @returns {void}
     */
    clearSelection() {
        this.selection.clear()
        this.infoCard?.hide()
    }

    /**
     * Card "Show on map" CTA: flies to the entity bounds — for regions the
     * main-cluster bounds when baked, else the full bounds — then closes the card.
     * @param {string} kind Entity kind: region/cluster/area/poi/problem.
     * @param {Object} properties Tile feature properties with bounds.
     * @returns {void}
     */
    showSelectionOnMap(kind, properties) {
        const bounds = this.selectionBounds(kind, properties)
        if (!bounds) return

        this.flyToBounds(bounds)
        this.clearSelection()
    }

    /**
     * Returns valid bounds for the selected entity, preferring a region's
     * baked main-cluster bounds when present.
     * @param {string} kind Entity kind: region/cluster/area/poi/problem.
     * @param {Object} properties Tile feature properties with bounds.
     * @returns {Array<Array<number>>|null} Southwest/northeast bounds or null.
     */
    selectionBounds(kind, properties) {
